let t;
let res;
let fps;
let cycle;
function setup() {
	createCanvas(windowWidth, windowHeight)
	t = 0;
	cycle = 0;
	res = 5;
	fps = 15;
}

function draw() {
	background(0, 10);
	if(t === 0) {
		beginShape();
	}

	let amp;
	let ampDelta;
	if (cycle % 2 === 0) {
		ampDelta = sin(t/fps/2) * 100 + 20;
		amp = sin(t/fps) * ampDelta + windowHeight / 2;
	} else if (cycle % 3 === 0) {
		ampDelta = sin(t/fps/2) * 100 + 20;
		amp = cos(t/fps) * ampDelta + windowHeight / 2;
	} else {
		ampDelta = cos(t/fps/2) * 100 + 20;
		amp = cos(t/fps) * ampDelta + windowHeight / 2;
	}
	strokeWeight(10);
	noFill();
	stroke(250, 0, 0);
	point(t, amp);
	strokeWeight(0.5);
	stroke(250);
	curveVertex(t, amp);
	endShape();
	t+=res;
	if (t > windowWidth) {
		t=0;
		cycle+=1;
	}
}

