class LineObj {
	constructor(i) {
		this.reset(i);
	}

	reset(i, gen, x, y) {
		this.i = i;
		this.y = random(0, windowHeight);
		this.w = random(lineMin, lineMax);
		this.x = x != null ? x -this.w : -this.w;
		this.direction = random([-1,1]);
		this.deltaX = map(this.w, lineMin, lineMax, 1, 10);
		this.thickness = map(this.w, lineMin, lineMax, 0.5, 25);

	}

	update() {
		this.x += this.deltaX;
		if((this.x + this.w) > (windowWidth + this.w)) {
			this.reset(this.i);
		}
	}

	draw() {
		stroke(255, 200);
		noFill();
		strokeWeight(this.thickness);
		line(this.x, this.y, this.x + this.w, this.y);
		noStroke();
		fill(color(255, 0, 0, 255));
		circle(this.x+this.w, this.y, this.thickness);
	}
}

let radius = 200;
const fps = 60;
let randOffset = 0;

function setup() {
	createCanvas(windowWidth, windowHeight)
}

function draw() {
	radius = cos(frameCount/fps/4) * 300;
	background(10, 5);
	push();
	translate(windowWidth/2, windowHeight/2);
	rotate(sin(frameCount/fps) + frameCount/fps/6);
	let circle1 = drawCircle(1, 0, 0, radius, 1, 200, 1);
	let circle2 = drawCircle(2, circle1.x, circle1.y, radius/2, 2, 230, -1);
	let circle3 = drawCircle(3, circle2.x, circle2.y, radius/4, 4, 240, 1);
	pop();
}

function drawCircle(gen, cx, cy, orbitR, speed, color, sign) {
      let angle = (frameCount / fps) * speed;
      let x = cx + sin(angle) * orbitR;
      let y = cy + cos(angle) * orbitR;

      noFill();

      let rndX = random(-randOffset, randOffset) * orbitR/10;
      let rndY = random(-randOffset, randOffset) * orbitR/10;
      if (gen === 1) {
    	strokeWeight(1);
    	stroke(color);
    	circle(x+rndX, y+rndY, sin(frameCount/fps) * orbitR);
    	stroke(250, 0, 0);
    	strokeWeight(3);
    	point(x+rndX, y+rndY);
      } else if (gen === 2) {
    	strokeWeight(0.75);
    	stroke(color);
    	circle(x+rndX, y+rndY, cos(frameCount/fps) * orbitR);
    	stroke(0, 200, 0);
    	strokeWeight(3);
    	point(x+rndX, y+rndY);
      } else if (gen === 3) {
      	strokeWeight(0.5);
      stroke(color);
      	circle(x+rndX, y+rndY, sin(frameCount/fps) * orbitR);
      	stroke(0,0, 250);
    	strokeWeight(3);
    	point(x+rndX, y+rndY);
      }

      if (gen === 1) {
    	strokeWeight(1);
    	stroke(color);
    	circle(x+rndX, y+rndY, sin(frameCount/fps-HALF_PI) * orbitR);
      } else if (gen === 2) {
    	strokeWeight(0.75);
    	stroke(color);
    	circle(x+rndX, y+rndY, cos(frameCount/fps-HALF_PI) * orbitR);
      } else if (gen === 3) {
      	strokeWeight(0.5);
    	stroke(color);
      	circle(x+rndX, y+rndY, sin(frameCount/fps-HALF_PI) * orbitR);
      }

      return { x, y };
 }

